<script setup lang="ts">
import { reactive, ref, watch } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { api } from '../api';
import { fail, params, sl } from '../safety-workspace';
const props=defineProps<{modelValue:boolean;source?:any;defaultType?:string}>(),emit=defineEmits<{'update:modelValue':[v:boolean];created:[task:any]}>();
const form=reactive({taskType:'EMERGENCY',sourceKey:'',title:'',requirement:'',responsibleName:'',dueAt:'',responseMode:'FIELD'}),sources=ref<any[]>([]),loading=ref(false),saving=ref(false),error=ref('');let initial='';
async function find(q=''){loading.value=true;try{const result=await api<any>(`/safety/workspace/events?${params({q,page:1,pageSize:50})}`);sources.value=[...(props.source?[props.source]:[]),...result.items].filter((s,i,all)=>all.findIndex(v=>v.id===s.id&&v.kind===s.kind)===i)}catch(e){error.value=fail(e)}finally{loading.value=false}}
function choose(){const source=sources.value.find(s=>`${s.kind}:${s.id}`===form.sourceKey);if(source&&!form.title)form.title=`${source.title}${form.taskType==='RECTIFICATION'?'整改':'应急处置'}`;}
async function close(){if(saving.value)return;if(JSON.stringify(form)!==initial){try{await ElMessageBox.confirm('任务尚未创建，是否放弃本次填写？','放弃未提交任务',{confirmButtonText:'放弃改动',cancelButtonText:'继续填写'});}catch{return}}emit('update:modelValue',false)}
async function save(){if(!form.sourceKey||!form.title.trim()||!form.requirement.trim()||!form.responsibleName.trim()||!form.dueAt)return ElMessage.warning('请完整填写来源、任务名称、要求、负责人和期限');saving.value=true;error.value='';try{const [sourceType,sourceId]=form.sourceKey.split(':'),task=await api<any>('/safety/workspace/tasks',{method:'POST',body:JSON.stringify({...form,sourceKey:undefined,sourceType,sourceId,dueAt:new Date(form.dueAt).toISOString()})});initial=JSON.stringify(form);emit('update:modelValue',false);emit('created',task);ElMessage.success(task.reused?'已有未办结任务，已打开该任务':'任务已下达')}catch(e){error.value=fail(e)}finally{saving.value=false}}
watch(()=>props.modelValue,v=>{if(v){Object.assign(form,{taskType:props.defaultType??'EMERGENCY',sourceKey:props.source?`${props.source.kind}:${props.source.id}`:'',title:props.source?`${props.source.title}${props.defaultType==='RECTIFICATION'?'整改':'应急处置'}`:'',requirement:'',responsibleName:'',dueAt:'',responseMode:'FIELD'});initial=JSON.stringify(form);error.value='';void find()}});
</script>
<template><el-dialog :model-value="modelValue" title="新建安全监管任务" width="min(680px,95vw)" class="safety-editor" :close-on-click-modal="false" :before-close="close" ><div v-if="error" class="safety-inline-error" role="alert">{{error}}</div><el-form label-position="top" class="safety-form-grid"><el-form-item label="任务类型" required><el-select v-model="form.taskType" aria-label="任务类型"><el-option label="应急处置" value="EMERGENCY"/><el-option label="整改任务" value="RECTIFICATION"/></el-select></el-form-item><el-form-item v-if="form.taskType==='EMERGENCY'" label="响应方式"><el-select v-model="form.responseMode" aria-label="响应方式"><el-option label="现场处置" value="FIELD"/><el-option label="远程处置" value="REMOTE"/></el-select></el-form-item><el-form-item label="关联事件" class="wide" required><el-select v-model="form.sourceKey" filterable remote :remote-method="find" :loading="loading" :disabled="!!source" aria-label="关联事件" placeholder="搜索事件编号、车辆或企业" @change="choose"><el-option v-for="item in sources" :key="`${item.kind}:${item.id}`" :value="`${item.kind}:${item.id}`" :label="`${sl(item.kind)} · ${item.title} · ${item.businessNo}`"/></el-select></el-form-item><el-form-item label="任务名称" class="wide" required><el-input v-model="form.title" aria-label="任务名称" maxlength="150"/></el-form-item><el-form-item label="负责人" required><el-input v-model="form.responsibleName" aria-label="任务负责人" maxlength="80" placeholder="企业承办负责人"/></el-form-item><el-form-item :label="form.taskType==='RECTIFICATION'?'整改期限':'处置期限'" required><el-date-picker v-model="form.dueAt" aria-label="任务期限" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item><el-form-item :label="form.taskType==='RECTIFICATION'?'整改要求':'处置要求'" class="wide" required><el-input v-model="form.requirement" type="textarea" :rows="5" maxlength="5000" show-word-limit aria-label="任务要求"/></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="close">取消</el-button><el-button type="primary" :loading="saving" @click="save">下达任务</el-button></template></el-dialog></template>
